beans_pony=json.loads((beans_old/'shots/pony/receipt.json').read_text())
beans_review={'approved': True, 'anatomy_checked': True, 'motion_checked': True, 'video_sha256': 'a489f9a1c227a4ee666e70defb52fbbd87f32bfeeeb137fc90351d1786f83d0a', 'reviewer': 'Codex visual review; not owner visual approval', 'reviewed_at': '2026-10-24T16:28:16.698891+00:00', 'scope': 'All 97 decoded frames inspected in seven sheets. Pony walks from behind puppy with alternating hoof lifts and weight-bearing plants, then nods and tilts head to Human. Four continuous legs and four distinct grounded hooves in the clear final poses; ordinary gait occlusion earlier, no duplicated, detached or displaced limb. One rump tail, mane remains along neck. Kitten stays correctly seated; puppy retains mouth-held coral ball. Human phone remains physically supported, no landscape artifacts. Seam from puppy ending: 35.42 dB PSNR, mean difference 2.63/255.'}
