beans_proc=Path('/proc')/str(beans_pid)
if beans_proc.exists():
 beans_cmd=(beans_proc/'cmdline').read_bytes().replace(b'\0',b' ').decode()
 if beans_cmd:
  assert str(beans_old/'render-wan-story.py') in beans_cmd, 'Unexpected process; do not interrupt'
  assert 'AWAITING_AGENT_VISUAL_REVIEW pony' in (beans_old/'production-run.log').read_text()[-1500:]
  os.killpg(beans_pid,signal.SIGTERM)
  for beans_wait in range(20):
   if not beans_proc.exists() or (beans_proc/'stat').read_text().split()[2]=='Z': break
   time.sleep(.5)
  else: raise RuntimeError('Previous renderer did not stop')
